CREATE TEMPORARY VIEW vsku_rmodel_mapping_${grass_region_without_quote} AS
SELECT
    *
FROM srdi_mart.dim_sr_data_warehouse_vsku_model_mapping_hf
where grass_region in (${grass_region}) and regional_date = ${regional_date} and regional_hour = ${regional_hour}
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW cspu_with_vitem_${grass_region_without_quote} AS
SELECT
*
from(
    SELECT
        *
        ,row_number() over (partition by cspu_id order by vsku_order_cnt_nd desc) as rn
    from(
        SELECT
             cspu_id
            ,vitem_id
            ,vsku_grow_period
            ,vsku_publish_local_date
            ,vsku_order_cnt_nd
        FROM vsku_rmodel_mapping_${grass_region_without_quote}
        group by
             cspu_id
            ,vitem_id
            ,vsku_grow_period
            ,vsku_publish_local_date
            ,vsku_order_cnt_nd
    ) a
) b
where rn=1
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_vsku_remapping_hf
partition(grass_region = ${grass_region}, local_date, local_hour, regional_date,regional_hour)
select
     1 as mapping_type
    ,cspu_id
    ,model_id
    ,item_id
    ,shop_id
    ,vitem_id
    ,vsku_grow_period
    ,vsku_publish_local_date
    ,vsku_order_cnt_nd

    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
from vsku_rmodel_mapping_${grass_region_without_quote}

union all

select
     0 as mapping_type
    ,a.cspu_id
    ,a.model_id
    ,a.item_id
    ,a.shop_id
    ,b.vitem_id
    ,b.vsku_grow_period
    ,b.vsku_publish_local_date
    ,b.vsku_order_cnt_nd

    ,a.local_date
    ,a.local_hour
    ,a.regional_date
    ,a.regional_hour
from all_cspu_${grass_region_without_quote} a
left join cspu_with_vitem_${grass_region_without_quote} b on a.cspu_id=b.cspu_id
left join vsku_rmodel_mapping_${grass_region_without_quote} c on a.model_id=c.model_id -- 这个join key 已经不够用了，但是我下边用的是 is null 所以也不会有错误
where b.cspu_id is not null and c.model_id is null
;
